describe('Navigation Menu Active Item Highlighting', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('nav').should('be.visible');
  });

  it('should highlight the active menu item when navigating to a page', () => {
    cy.get('nav a[href="/about"]').click();
    cy.get('nav a[href="/about"]').should('have.class', 'active');
    cy.get('nav a[href="/"]').should('not.have.class', 'active');
  });

  it('should maintain active state on page reload', () => {
    cy.get('nav a[href="/services"]').click();
    cy.get('nav a[href="/services"]').should('have.class', 'active');
    cy.reload();
    cy.get('nav a[href="/services"]').should('have.class', 'active');
  });

  it('should update active item when navigating between multiple pages', () => {
    cy.get('nav a[href="/about"]').click();
    cy.get('nav a[href="/about"]').should('have.class', 'active');

    cy.get('nav a[href="/contact"]').click();
    cy.get('nav a[href="/contact"]').should('have.class', 'active');
    cy.get('nav a[href="/about"]').should('not.have.class', 'active');
  });

  it('should highlight home menu item on initial page load', () => {
    cy.get('nav a[href="/"]').should('have.class', 'active');
  });

  it('should apply active styling with correct visual indicators', () => {
    cy.get('nav a[href="/about"]').click();
    cy.get('nav a[href="/about"]').should('have.class', 'active');
    cy.get('nav a[href="/about"]').should('have.css', 'color').and('not.equal', 'rgb(0, 0, 0)');
  });

  it('should handle nested menu items correctly', () => {
    cy.get('nav a[href="/products"]').click();
    cy.get('nav a[href="/products"]').should('have.class', 'active');
    cy.get('nav a[href="/products/electronics"]').click();
    cy.get('nav a[href="/products/electronics"]').should('have.class', 'active');
    cy.get('nav a[href="/products"]').should('have.class', 'active');
  });

  it('should only have one active menu item at a time', () => {
    cy.get('nav a').each(($link) => {
      cy.wrap($link).click();
    });

    cy.get('nav a.active').should('have.length', 1);
  });
});
